function Newsletter({ compact = false }) {
  const [email, setEmail] = useState('')
  const [done, setDone] = useState(false)
  const { notify } = useStore()
  return done ? <p className="success-note"><Check size={16}/> You’re on the list. Thank you.</p> : <form className={`newsletter ${compact ? 'compact' : ''}`} onSubmit={event => { event.preventDefault(); setDone(true); notify('You’re on the 7FEELINGS list') }}><input required type="email" placeholder="Your email address" value={email} onChange={event => setEmail(event.target.value)}/><button aria-label="Subscribe"><ArrowRight/></button></form>
}

function ProductCard({ product }) {
  const { wish, toggleWish, add } = useStore()
  const [sizeOpen, setSizeOpen] = useState(false)
  const [selected, setSelected] = useState('')
  const [quick, setQuick] = useState(false)
  const [touchImage, setTouchImage] = useState(0)
  const touchStart = useRef(null)
  const ignoreTouchClick = useRef(false)
  const saved = wish.some(item => item.id === product.id)
  const alternateImage = product.images?.[1]
  const handleTouchStart = event => { const touch = event.touches[0]; touchStart.current = { x: touch.clientX, y: touch.clientY }; ignoreTouchClick.current = false }
  const handleTouchEnd = event => {
    if (!alternateImage || !touchStart.current) return
    const touch = event.changedTouches[0]
    const dx = touch.clientX - touchStart.current.x
    const dy = touch.clientY - touchStart.current.y
    if (Math.abs(dx) > 36 && Math.abs(dx) > Math.abs(dy) + 18) {
      setTouchImage(value => value === 0 ? 1 : 0)
      ignoreTouchClick.current = true
      window.setTimeout(() => { ignoreTouchClick.current = false }, 400)
    }
    touchStart.current = null
  }
  const openProduct = event => { if (ignoreTouchClick.current) { event.preventDefault(); event.stopPropagation(); ignoreTouchClick.current = false } }
  return <article className={`product-card${alternateImage ? ' has-alternate' : ''}`}><div className="product-photo-wrap"><Link to={`/product/${product.id}`} className={`product-photo${touchImage === 1 ? ' touch-alternate' : ''}`} onTouchStart={handleTouchStart} onTouchEnd={handleTouchEnd} onClick={openProduct}><img className="product-primary" src={product.image} loading="lazy" alt={product.name}/>{alternateImage && <img className="product-alternate" src={alternateImage} loading="lazy" alt=""/>}<span className="tag">{product.isNew ? 'NEW ARRIVAL' : product.isBest ? 'BESTSELLER' : '7F EDIT'}</span><span className="discount-tag">-{Math.round((1-product.price/product.oldPrice)*100)}%</span></Link><button className={`heart-button ${saved ? 'active' : ''}`} onClick={() => toggleWish(product)} aria-label={saved ? 'Remove from wishlist' : 'Add to wishlist'}><Heart size={17} fill={saved ? 'currentColor' : 'none'}/></button><div className="product-photo-actions"><button className="quick-view" onClick={() => setQuick(true)}>Quick view <ArrowUpRight size={14}/></button><button className="card-quick-add" onClick={() => setSizeOpen(value => !value)}><Plus size={13}/> Quick add</button></div>{sizeOpen && <div className="quick-size-panel"><div><b>Choose a size</b><button onClick={() => setSizeOpen(false)} aria-label="Close size selector"><X size={14}/></button></div><div className="quick-size-options">{product.sizes.map(size => <button key={size} className={selected === size ? 'selected' : ''} onClick={() => setSelected(size)}>{size}</button>)}</div><button className="quick-add-confirm" disabled={!selected} onClick={() => { if (add(product, selected)) { setSizeOpen(false); setSelected('') } }}>Add to bag <ArrowRight size={14}/></button></div>}</div><div className="product-info"><Link to={`/product/${product.id}`} className="product-name">{product.name}</Link><span>{amount(product.price)} <del>{amount(product.oldPrice)}</del></span></div><div className="product-meta">{product.category} <span>·</span> {product.fabric}</div>{quick && <QuickView product={product} onClose={() => setQuick(false)}/>}</article>
}

function QuickView({ product, onClose }) {
  const { add, wish, toggleWish } = useStore()
  const [size, setSize] = useState('')
  useEffect(() => { const close = event => event.key === 'Escape' && onClose(); window.addEventListener('keydown', close); return () => window.removeEventListener('keydown', close) }, [onClose])
  return <div className="modal-backdrop" onMouseDown={event => event.target === event.currentTarget && onClose()}><section className="quick-view-modal"><button className="modal-close" onClick={onClose} aria-label="Close quick view"><X/></button><img className="quick-view-image" src={product.image} alt={product.name}/><div className="quick-view-copy"><span className="eyebrow">{product.category} · 7FEELINGS</span><h2>{product.name}</h2><div className="detail-price">{amount(product.price)} <del>{amount(product.oldPrice)}</del><span>{Math.round((1-product.price/product.oldPrice)*100)}% off</span></div><p>{product.description}</p><b className="quick-size-label">Choose your size</b><div className="size-select">{product.sizes.map(item => <button className={size === item ? 'selected' : ''} onClick={() => setSize(item)} key={item}>{item}</button>)}</div><button className="button button-dark add-button" onClick={() => { if (add(product, size)) onClose() }}>Add to bag <ShoppingBag size={16}/></button><button className="quick-wish" onClick={() => toggleWish(product)}><Heart size={16}/> {wish.some(item => item.id === product.id) ? 'Saved to wishlist' : 'Add to wishlist'}</button><Link className="text-link" to={`/product/${product.id}`} onClick={onClose}>View full details <ArrowUpRight size={14}/></Link></div></section></div>
}

function ProductGrid({ items, carousel = false, id }) {
  const track = useRef(null)
  const scroll = direction => track.current?.scrollBy({ left: direction * (track.current.clientWidth * .8), behavior: 'smooth' })
  if (carousel) return <div className="carousel-wrap"><div className="product-carousel" id={id} ref={track}>{items.map(product => <div className="carousel-product" key={product.id}><ProductCard product={product}/></div>)}</div><div className="carousel-controls"><button onClick={() => scroll(-1)} aria-label="Scroll products left"><ArrowLeft size={17}/></button><button onClick={() => scroll(1)} aria-label="Scroll products right"><ArrowRight size={17}/></button></div></div>
  return <div className="product-grid">{items.map(product => <ProductCard key={product.id} product={product}/>)}</div>
}

